"""Tier 2: prose, scored against a written rubric by a model.

Three decisions that make this defensible
------------------------------------------

**The judge never sees who wrote the answer.** No "this was generated by
Claude", no model name, no framing. It sees the source XML, the question, the
rubric, and the answer. Anything else invites the model to grade the author
rather than the text.

**The rubric lives with the case, not in the judge prompt.** Each case carries
its own anchors for what a 5 and a 1 look like, in that case's specific terms —
including, where it matters, the exact hallucination the case exists to catch.
A generic "rate this 1-5 for quality" prompt produces a number that drifts
between runs and means nothing across cases.

**The judge is calibrated, and the agreement rate is written down.** Spot-check
ten judgements by hand, record how often you agreed, keep it in
``golden/calibration.md``. An uncalibrated judge is an unmeasured instrument,
and "we score 4.2" is not a claim until you know how often the scorer is right.

The honest limitation, stated rather than hidden: a judge sharing a family with
the system under test can share its blind spots. The mitigations are that facts
never reach it (tier 1 owns those), the rubrics name specific failure modes
rather than asking for a vibe, and the agreement rate is tracked over time.
Using a different model family for judging is the further step, and the cost
trade is a real one rather than an oversight.
"""

from __future__ import annotations

import os
from dataclasses import dataclass
from pathlib import Path

from .cases import Case

JUDGE_MODEL = "claude-sonnet-5"
SUT_MODEL = "claude-sonnet-5"

_SCORE_TOOL = {
    "name": "record_score",
    "description": "Record the rubric score for one answer.",
    "input_schema": {
        "type": "object",
        "properties": {
            "score": {"type": "integer", "minimum": 1, "maximum": 5},
            "reasoning": {
                "type": "string",
                "description": "Two sentences maximum, citing the rubric clause that decided the score.",
            },
            "rubric_violations": {
                "type": "array",
                "items": {"type": "string"},
                "description": "Specific rubric clauses the answer failed. Empty if none.",
            },
        },
        "required": ["score", "reasoning", "rubric_violations"],
    },
}


@dataclass(frozen=True)
class Judgement:
    case_id: str
    score: int
    min_score: int
    reasoning: str
    violations: list[str]
    answer: str

    @property
    def passed(self) -> bool:
        return self.score >= self.min_score


class NoApiKey(RuntimeError):
    """Raised so callers can skip tier 2 rather than fail it.

    A missing key means the tier did not run. Reporting that as a failure
    would train everyone to ignore a red build, which is how eval gates die.
    """


def _client():
    key = os.environ.get("ANTHROPIC_API_KEY")
    if not key:
        raise NoApiKey("ANTHROPIC_API_KEY not set — tier 2 skipped, not failed")
    from anthropic import Anthropic  # imported lazily: tier 1 must not need it
    return Anthropic(api_key=key)


def produce_answer(case: Case, repo_root: Path) -> str:
    """Run the system under test: explain a Flow from its XML."""
    client = _client()
    xml = (repo_root / case.target).read_text()
    response = client.messages.create(
        model=SUT_MODEL,
        max_tokens=800,
        temperature=0,
        messages=[{
            "role": "user",
            "content": (
                f"{case.question}\n\nBe precise: describe only what this "
                f"metadata states.\n\n{xml}"
            ),
        }],
    )
    return "".join(b.text for b in response.content if b.type == "text").strip()


def judge(case: Case, answer: str, repo_root: Path) -> Judgement:
    client = _client()
    xml = (repo_root / case.target).read_text()
    response = client.messages.create(
        model=JUDGE_MODEL,
        max_tokens=1000,
        temperature=0,
        tools=[_SCORE_TOOL],
        tool_choice={"type": "tool", "name": "record_score"},
        messages=[{
            "role": "user",
            "content": (
                "You are grading an answer against a rubric. Apply the rubric "
                "literally; do not reward fluency the rubric does not ask for, "
                "and do not penalise brevity the rubric does not forbid.\n\n"
                f"SOURCE METADATA:\n{xml}\n\n"
                f"QUESTION:\n{case.question}\n\n"
                f"RUBRIC:\n{case.rubric}\n\n"
                f"ANSWER TO GRADE:\n{answer}"
            ),
        }],
    )
    block = next(b for b in response.content if b.type == "tool_use")
    return Judgement(
        case_id=case.id,
        score=block.input["score"],
        min_score=case.min_score,
        reasoning=block.input["reasoning"],
        violations=block.input.get("rubric_violations", []),
        answer=answer,
    )


def run(cases: list[Case], repo_root: Path) -> list[Judgement]:
    return [
        judge(case, produce_answer(case, repo_root), repo_root)
        for case in cases if case.tier == 2
    ]
